private function prepareSettings(array $settings): array
{
    $settings['id'] = (int) $settings['id'];
    $settings['title'] = \Bitrix\Main\Text\Encoding::convertEncodingToCurrent($settings['title']);

    // Allowlist VALID_PERMISSION_IDs
    $validPermissionIds = [96, 97, 98, 99];
    $filteredRights = [];
    foreach ($settings['accessRights'] ?? [] as $right)
    {
        $id = (int) $right['id'];
        $value = (int) $right['value'];
        if (in_array($id, $validPermissionIds) && in_array($value, [0, 1, 2, 3]))
        {
            $filteredRights[] = ['id' => $id, 'value' => $value];
        }
    }
    $settings['accessRights'] = $filteredRights;

    // Validate accessCodes format
    if (!empty($settings['accessCodes']))
    {
        $settings['accessCodes'] = array_filter($settings['accessCodes'], function($code) {
            return is_string($code) && preg_match('/^[\w\+]+:[\w\+]+$/', $code);
        });
    }

    return $settings;
}
